import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { SolicitudApoyo } from '../models/solicitud.apoyo';
import { firstValueFrom } from 'rxjs';
import { SolicitudApoyoModalidad } from '../models/solicitud.apoyo.modalidad';
import { ApoyoTipoInversion } from '../models/apoyo.tipo.inversion';

@Injectable({
  providedIn: 'any'
})
export class SolicitudApoyoService extends SuperService<SolicitudApoyo> {
  protected override model: string = "solicitudes_apoyos";
  protected override columns: (keyof SolicitudApoyo)[] = [
    'descripcion_uso_recurso',
    'nombre_comercial',
    'giro_comercial',
    'red_social',
    'sucursal_id',
    'programas_apoyo_id',
    'datos_personal_id',
    'usuario_id',
    'razon_social_negocio',
    'nombre_comercial_negocio',
    'antiguedad_negocio',
    'empleos_imss_h',
    'empleos_imss_m',
    'empleos_imss_nb',
    'empleos_informales_h',
    'empleos_informales_m',
    'empleos_informales_nb',
    'empleos_a_generar_h',
    'empleos_a_generar_m',
    'empleos_a_generar_nb',
    'empleos_generados_h',
    'empleos_generados_m',
    'empleos_generados_nb',
    'actividades_economica_id',
    'calle_fiscal',
    'num_int_fiscal',
    'num_ext_fiscal',
    'colonia_fiscal',
    'cp_fiscal',
    'folio',
    'municipio_fiscal',
    'localidad_fiscal',
    'telefono_casa_fiscal',
    'telefono_celular_fiscal',
    'telefono_oficina_fiscal',
    'correo_fiscal',
    'latitud_fiscal',
    'longitud_fiscal',
    'calle_negocio',
    'num_int_negocio',
    'num_ext_negocio',
    'colonia_negocio',
    'cp_negocio',
    'municipio_negocio',
    'localidad_negocio',
    'telefono_casa_negocio',
    'telefono_celular_negocio',
    'telefono_oficina_negocio',
    'correo_negocio',
    'inicio_actividad_sat_negocio',
    'antiguedad_negocio',
    'referencias_dom_fiscal',
    'referencias_dom_negocio',
    'latitud_negocio',
    'longitud_negocio',
    'caso_urbem',
    'usuario_nombre_migrado',
    'expediente',
    'fuente_informacion',
  ]

  constructor(injector: Injector) {
    super(injector)
  }

  public async avanzarEstado(modalidad: SolicitudApoyoModalidad | undefined) {
    if (!modalidad) return
    const api = 'api/apoyos/ajustar_estado'
    const res = await firstValueFrom(this.api.post<SolicitudApoyoModalidad>(api, { id: modalidad.id }))
    if (res.status && res.data) {
      modalidad.estado = res.data.estado
    }
  }

  public async retrocederEstado(modalidad: SolicitudApoyoModalidad | undefined) {
    if (!modalidad) return
    const api = 'api/apoyos/ajustar_estado/retroceder'
    const res = await firstValueFrom(this.api.post<SolicitudApoyoModalidad>(api, { id: modalidad.id }))
    if (res.status && res.data) {
      modalidad.estado = res.data.estado
    }
  }

  public modalidadActual(solicitudApoyo: SolicitudApoyo | undefined): SolicitudApoyoModalidad | undefined {
    if (!solicitudApoyo || !solicitudApoyo.solicitudes_apoyos_modalidades) return
    return solicitudApoyo.solicitudes_apoyos_modalidades[solicitudApoyo.solicitudes_apoyos_modalidades.length - 1]
  }

  public totalModalidadActualFromSolicitudApoyo(solicitudApoyo: SolicitudApoyo | undefined) {
    const modalidadActual = this.modalidadActual(solicitudApoyo)
    if (!modalidadActual?.solicitudes_apoyos_modalidades_cotizaciones) return;
    return modalidadActual.solicitudes_apoyos_modalidades_cotizaciones.reduce((acc, cot) => acc + +(cot.monto), 0)
  }

  public tiposInversionesActuales(solicitudApoyo: SolicitudApoyo | undefined, modalidadActual?: SolicitudApoyoModalidad): ApoyoTipoInversion[] {
    if (!solicitudApoyo?.solicitudes_apoyos_modalidades) return [];
    if (!modalidadActual) {
      modalidadActual = this.modalidadActual(solicitudApoyo)
    }
    if (modalidadActual && solicitudApoyo.solicitudes_apoyos_modalidades.length == 1) {
      return (solicitudApoyo?.apoyos_tipos_inversiones ?? []).filter(tipo => tipo.solicitud_modalidad_id == modalidadActual!.id || tipo.solicitud_modalidad_id === null) ?? []
    }
    if (modalidadActual && solicitudApoyo.solicitudes_apoyos_modalidades.length > 1) {
      return (solicitudApoyo?.apoyos_tipos_inversiones ?? []).filter(tipo => tipo.solicitud_modalidad_id == (modalidadActual!.id)) ?? []
    }
    if (solicitudApoyo.solicitudes_apoyos_modalidades.length == 0) {
      return (solicitudApoyo.apoyos_tipos_inversiones ?? []).filter(tipo => tipo.solicitud_modalidad_id === null)
    }
    return [];
  }
}